// ---------------------------------------------------------------------------
// Motif signature : "sentier réseau"
// ---------------------------------------------------------------------------
function NetworkTrail({ color }) {
  return (
    <svg className="absolute inset-0 w-full h-full opacity-[0.14] pointer-events-none" viewBox="0 0 400 140" preserveAspectRatio="none">
      <path d="M0 90 C 60 30, 120 130, 180 60 S 300 20, 400 70" stroke={color} strokeWidth="1.5" strokeDasharray="1 9" strokeLinecap="round" fill="none" />
      {[20, 95, 180, 260, 340, 390].map((x, i) => (
        <circle key={i} cx={x} cy={i % 2 === 0 ? 55 : 85} r="3" fill={color} />
      ))}
    </svg>
  );
}

// Affiche la vraie image du produit (venue d'Odoo). Si elle n'existe pas
// ou ne charge pas, on retombe proprement sur l'icone de remplacement,
// sans casser l'affichage.
function ProductImage({ src, iconSize = 22 }) {
  const [failed, setFailed] = useState(false);
  if (!src || failed) {
    return <Monitor size={iconSize} color={`${TOKENS.ink}33`} />;
  }
  return (
    <img
      src={src}
      alt=""
      className="w-full h-full object-contain"
      onError={() => setFailed(true)}
    />
  );
}

function StarRow({ rating, size = 12 }) {
  return (
    <div className="flex items-center gap-0.5">
      {[1, 2, 3, 4, 5].map((n) => (
        <Star key={n} size={size} color={TOKENS.ochre} fill={n <= Math.round(rating) ? TOKENS.ochre : "transparent"} />
      ))}
    </div>
  );
}

