function BottomNav({ screen, setScreen, accent, cartCount }) {
  const items = [
    { key: "home", icon: HomeIcon, label: "Accueil" },
    { key: "categories", icon: Grid3x3, label: "Catégories" },
    { key: "cart", icon: ShoppingCart, label: "Panier", badge: cartCount },
    { key: "account", icon: User, label: "Compte" },
  ];
  return (
    <nav
      className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white flex items-center justify-around py-2.5 z-20"
      style={{ borderTop: `1px solid ${TOKENS.ink}0F` }}
    >
      {items.map(({ key, icon: Icon, label, badge }) => {
        const active = screen === key;
        return (
          <button key={key} className="flex flex-col items-center gap-0.5 relative" onClick={() => setScreen(key)}>
            <div className="relative">
              <Icon size={19} color={active ? accent : `${TOKENS.ink}66`} />
              {badge > 0 && (
                <span
                  className="absolute -top-1.5 -right-2 text-[8px] font-semibold w-3.5 h-3.5 rounded-full flex items-center justify-center"
                  style={{ background: TOKENS.clay, color: TOKENS.paper }}
                >
                  {badge}
                </span>
              )}
            </div>
            <span className="text-[10px]" style={{ color: active ? accent : `${TOKENS.ink}66` }}>{label}</span>
          </button>
        );
      })}
    </nav>
  );
}

