function CategoriesScreen({ config, accent, onBrowseCategory, onOpenSearch, allProducts, allProductsLoading }) {
  const [active, setActive] = useState(0);
  const current = config.categories[active];

  // Produits du catalogue reel qui appartiennent a la categorie actuellement
  // selectionnee dans la colonne de gauche.
  const currentCategoryProducts = useMemo(() => {
    if (!allProducts) return [];
    return allProducts.filter((p) => matchesCategoryFilter(p, current.label));
  }, [allProducts, current.label]);

  // Liste officielle des sous-categories (verifiee sur www.z-reseaux.com),
  // avec le nombre reel de produits en direct dans chacune.
  const subcategories = useMemo(() => {
    const officialList = ODOO_SUBCATEGORIES[current.label] || [];
    return officialList.map((label) => [label, countInSubcategory(currentCategoryProducts, label)]);
  }, [currentCategoryProducts, current.label]);

  return (
    <div className="flex flex-col pb-24" style={{ minHeight: "70vh" }}>
      <div className="px-4 py-3">
        <button onClick={onOpenSearch} className="w-full flex items-center gap-2 rounded-xl px-3 py-2.5 bg-white" style={{ border: `1px solid ${TOKENS.ink}14` }}>
          <Search size={15} color={TOKENS.ink} opacity={0.5} />
          <span className="text-xs" style={{ color: `${TOKENS.ink}66` }}>Rechercher un produit…</span>
        </button>
      </div>
      <div className="flex flex-1 min-h-0">
        <div className="w-24 flex-shrink-0 overflow-y-auto" style={{ background: "white", borderRight: `1px solid ${TOKENS.ink}0F`, maxHeight: "calc(100vh - 130px)" }}>
          {config.categories.map(({ icon: Icon, label }, i) => {
            const isActive = i === active;
            return (
              <button key={label} onClick={() => setActive(i)} className="w-full flex flex-col items-center gap-1.5 py-3.5 relative" style={{ background: isActive ? TOKENS.paper : "white" }}>
                {isActive && <span className="absolute left-0 top-2 bottom-2 w-[3px] rounded-r" style={{ background: accent }} />}
                <div className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: isActive ? `${accent}1A` : `${TOKENS.ink}0A` }}>
                  <Icon size={15} color={isActive ? accent : `${TOKENS.ink}88`} />
                </div>
                <span className="text-[9.5px] text-center leading-tight px-1 line-clamp-3" style={{ color: isActive ? TOKENS.ink : `${TOKENS.ink}77`, fontWeight: isActive ? 600 : 400 }}>{label}</span>
              </button>
            );
          })}
        </div>
        <div className="flex-1 px-4 py-4">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-sm font-semibold" style={{ fontFamily: TOKENS.displayFont, color: TOKENS.ink }}>{current.label}</h2>
            {!allProductsLoading && <span className="text-[10px]" style={{ color: `${TOKENS.ink}55` }}>{currentCategoryProducts.length} produits</span>}
          </div>
          <button
            onClick={() => onBrowseCategory(current.label)}
            className="w-full rounded-xl py-2.5 mb-3 text-xs font-semibold"
            style={{ background: `${accent}12`, color: accent }}
          >
            Voir tous les produits « {current.label} »
          </button>

          {allProductsLoading && (
            <p className="text-xs text-center py-6" style={{ color: `${TOKENS.ink}55` }}>Chargement des sous-catégories…</p>
          )}

          {!allProductsLoading && (
            <div className="grid grid-cols-2 gap-2.5">
              {subcategories.map(([label, count]) => (
                <button
                  key={label}
                  onClick={() => onBrowseCategory(current.label, label)}
                  className="flex flex-col items-center gap-1.5 rounded-xl py-3.5 px-2 bg-white text-center"
                  style={{ border: `1px solid ${TOKENS.ink}0F` }}
                >
                  <div className="w-12 h-12 rounded-lg flex items-center justify-center" style={{ background: TOKENS.sand }}>
                    <Monitor size={18} color={`${TOKENS.ink}33`} />
                  </div>
                  <span className="text-[10.5px] leading-tight line-clamp-2" style={{ color: TOKENS.ink }}>{label}</span>
                  <span className="text-[9px]" style={{ color: `${TOKENS.ink}55` }}>{count} produit{count > 1 ? "s" : ""}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

