function SearchScreen({ allProducts, accent, openProduct, loading }) {
  const [query, setQuery] = useState("");
  const results = useMemo(() => {
    if (!query.trim()) return [];
    const q = normalize(query);
    return (allProducts || []).filter((p) => normalize(p.name).includes(q) || normalize(p.ref).includes(q));
  }, [query, allProducts]);

  return (
    <div className="pb-24 px-5 pt-4">
      <div className="flex items-center gap-2 rounded-xl px-3 py-2.5 bg-white mb-4" style={{ border: `1.5px solid ${accent}` }}>
        <Search size={16} color={accent} />
        <input
          autoFocus
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Rechercher un produit, une référence…"
          className="flex-1 text-sm outline-none bg-transparent"
          style={{ color: TOKENS.ink }}
        />
      </div>

      {loading && (
        <p className="text-xs text-center py-6" style={{ color: `${TOKENS.ink}66` }}>Chargement du catalogue…</p>
      )}

      {!loading && query.trim() === "" && (
        <p className="text-xs text-center py-6" style={{ color: `${TOKENS.ink}55` }}>Tapez un mot pour chercher parmi les {(allProducts || []).length} produits</p>
      )}

      {!loading && query.trim() !== "" && (
        <>
          <p className="text-xs mb-3" style={{ color: `${TOKENS.ink}66` }}>{results.length} résultat{results.length > 1 ? "s" : ""}</p>
          <div className="grid grid-cols-2 gap-3">
            {results.slice(0, 40).map((p) => (
              <button key={p.id} onClick={() => openProduct(p)} className="rounded-xl bg-white overflow-hidden text-left" style={{ border: `1px solid ${TOKENS.ink}0F` }}>
                <div className="h-24 flex items-center justify-center" style={{ background: TOKENS.sand }}>
                  <ProductImage src={p.image} iconSize={22} />
                </div>
                <div className="p-2.5">
                  <p className="text-[11px] leading-snug font-medium line-clamp-2 h-7" style={{ color: TOKENS.ink }}>{p.name}</p>
                  {p.ref && <p className="text-[9px] mt-0.5" style={{ color: `${TOKENS.ink}55` }}>Réf. {p.ref}</p>}
                  <span className="text-[13px] font-semibold block mt-1" style={{ fontFamily: TOKENS.displayFont, color: accent }}>{formatF(p.price)} F</span>
                </div>
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function CartScreen({ cart, updateQty, removeItem, accent, goToCheckout }) {
  const items = Object.values(cart);
  const subtotal = items.reduce((s, it) => s + it.price * it.qty, 0);
  const livraison = items.length > 0 ? 2000 : 0;
  const total = subtotal + livraison;

  return (
    <div className="pb-32">
      {items.length === 0 ? (
        <div className="flex flex-col items-center justify-center px-8 text-center gap-3 py-20">
          <ShoppingBag size={40} color={`${TOKENS.ink}33`} />
          <p className="text-sm font-medium" style={{ color: TOKENS.ink }}>Votre panier est vide</p>
          <p className="text-xs" style={{ color: `${TOKENS.ink}66` }}>Parcourez les catégories pour trouver votre bonheur.</p>
        </div>
      ) : (
        <>
          <div className="px-5 pt-4 space-y-3">
            {items.map((it) => (
              <div key={it.id} className="flex gap-3 rounded-xl p-3 bg-white" style={{ border: `1px solid ${TOKENS.ink}0F` }}>
                <div className="w-16 h-16 rounded-lg flex-shrink-0 flex items-center justify-center" style={{ background: TOKENS.sand }}>
                  <ProductImage src={it.image} iconSize={18} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-medium leading-snug line-clamp-2" style={{ color: TOKENS.ink }}>{it.name}</p>
                  <div className="flex items-center justify-between mt-2">
                    <span className="text-sm font-semibold" style={{ fontFamily: TOKENS.displayFont, color: accent }}>{formatF(it.price)} F</span>
                    <div className="flex items-center gap-2 rounded-lg px-1" style={{ border: `1px solid ${TOKENS.ink}22` }}>
                      <button className="w-6 h-6 flex items-center justify-center" onClick={() => updateQty(it.id, -1)}><Minus size={11} color={TOKENS.ink} /></button>
                      <span className="text-xs w-3 text-center" style={{ color: TOKENS.ink }}>{it.qty}</span>
                      <button className="w-6 h-6 flex items-center justify-center" onClick={() => updateQty(it.id, 1)}><Plus size={11} color={TOKENS.ink} /></button>
                    </div>
                  </div>
                </div>
                <button className="self-start" onClick={() => removeItem(it.id)}><Trash2 size={14} color={`${TOKENS.ink}55`} /></button>
              </div>
            ))}
          </div>

          <div className="px-5 mt-5 space-y-1.5">
            <div className="flex justify-between text-xs" style={{ color: `${TOKENS.ink}99` }}><span>Sous-total</span><span>{formatF(subtotal)} F</span></div>
            <div className="flex justify-between text-xs" style={{ color: `${TOKENS.ink}99` }}><span>Livraison</span><span>{formatF(livraison)} F</span></div>
          </div>
        </>
      )}

      {items.length > 0 && (
        <div className="fixed bottom-16 left-0 right-0 max-w-md mx-auto bg-white flex items-center gap-3 px-5 py-3.5" style={{ borderTop: `1px solid ${TOKENS.ink}0F` }}>
          <div>
            <p className="text-[10px]" style={{ color: `${TOKENS.ink}66` }}>Total</p>
            <p className="text-base font-semibold" style={{ fontFamily: TOKENS.displayFont, color: TOKENS.ink }}>{formatF(total)} F</p>
          </div>
          <button className="flex-1 rounded-xl py-3 text-sm font-semibold" style={{ background: accent, color: TOKENS.paper }} onClick={goToCheckout}>
            Commander ({items.length})
          </button>
        </div>
      )}
    </div>
  );
}

